      const hasSpec = SPECS_BY_MARKET.has(m.address);
      console.log(
        `  eligible  cutoff=${m.evidenceCutoffAt} p(yes)=${m.odds.yes.toFixed(3)} spec=${hasSpec ? "yes" : "no "}  ${m.question.slice(0, 62)}`,
      );
    }
    for (const s of report.marketSkips) {
